#!/usr/bin/env bash
# Run this in AWS CloudShell (your own console session — never Claude's).
# Does two things Claude's IAM identity (claude-code-aws-agent) is explicitly
# denied from doing:
#   1. Drops the 245 FK constraints blocking the DMS full reload of Aurora
#      (Aurora is a DMS-fed replica with no direct write traffic yet -- these
#      are restorable any time from aurora-fk-restore-2026-08-12.sql).
#   2. Creates the `authenticator` Postgres role PostgREST needs, and stores
#      its connection string in Secrets Manager.
# The master secret's password is never printed or echoed anywhere -- RDS
# Data API authenticates using the secret ARN directly.
set -euo pipefail

REGION="eu-central-1"
CLUSTER_ARN="arn:aws:rds:eu-central-1:472838866351:cluster:vitana-aurora-prod"
DB="vitana"

echo "=== Resolving Aurora master secret ==="
# --no-paginate is load-bearing here: list-secrets auto-paginates, and
# --query is applied PER PAGE by the CLI, not to the combined result set.
# With ~80 secrets in this account spread across multiple pages, most pages
# have no match (prints "None") and exactly one page has the real ARN --
# without --no-paginate, $MASTER_SECRET_ARN ends up as a multi-line blob of
# "None"s with the real ARN buried in the middle, which silently poisons
# every use of the variable below.
MASTER_SECRET_ARN=$(aws secretsmanager list-secrets --region "$REGION" --no-paginate \
  --query "SecretList[?starts_with(Name, 'rds!cluster-')].ARN | [0]" --output text)

# Defensive check: this must be exactly one line and look like an ARN. If
# pagination bites again for any reason, fail loudly here instead of
# passing garbage to get-secret-value.
LINE_COUNT=$(printf '%s' "$MASTER_SECRET_ARN" | wc -l)
if [ -z "$MASTER_SECRET_ARN" ] || [ "$MASTER_SECRET_ARN" == "None" ] || [ "$LINE_COUNT" -gt 0 ] || [[ "$MASTER_SECRET_ARN" != arn:aws:secretsmanager:* ]]; then
  echo "ERROR: could not cleanly resolve the RDS-managed master secret (got: '$MASTER_SECRET_ARN'). Aborting." >&2
  exit 1
fi
echo "Using master secret: $MASTER_SECRET_ARN"

# Safety check (lesson from earlier today): confirm the secret actually has
# content before trusting it for anything, without ever printing the value.
SECRET_LEN=$(aws secretsmanager get-secret-value --region "$REGION" \
  --secret-id "$MASTER_SECRET_ARN" --query 'SecretString' --output text | wc -c)
if [ "$SECRET_LEN" -lt 20 ]; then
  echo "ERROR: master secret looks empty/too short ($SECRET_LEN chars). Aborting." >&2
  exit 1
fi
echo "Master secret looks populated ($SECRET_LEN chars). Proceeding."
echo

run_sql() {
  local sql="$1"
  aws rds-data execute-statement --region "$REGION" \
    --resource-arn "$CLUSTER_ARN" --secret-arn "$MASTER_SECRET_ARN" \
    --database "$DB" --sql "$sql"
}

echo "=== Step 1: Dropping 245 FK constraints on Aurora (unblocks DMS reload) ==="
ok=0
fail=0
if run_sql 'ALTER TABLE messages DROP CONSTRAINT messages_parent_message_id_fkey;' > /dev/null 2>>/tmp/fk_drop_errors.log; then ok=$((ok+1)); else fail=$((fail+1)); echo "FAILED: ALTER TABLE messages DROP CONSTRAINT messages_parent_message_id_fkey;" >> /tmp/fk_drop_errors.log; fi
if run_sql 'ALTER TABLE scheduled_posts DROP CONSTRAINT scheduled_posts_post_id_fkey;' > /dev/null 2>>/tmp/fk_drop_errors.log; then ok=$((ok+1)); else fail=$((fail+1)); echo "FAILED: ALTER TABLE scheduled_posts DROP CONSTRAINT scheduled_posts_post_id_fkey;" >> /tmp/fk_drop_errors.log; fi
