echo "=== Step 2: Creating the 'authenticator' role for PostgREST ==="
AUTH_PW=$(openssl rand -base64 32 | tr -d '=+/' | head -c 40)
if [ -z "$AUTH_PW" ] || [ "${#AUTH_PW}" -lt 20 ]; then
  echo "ERROR: generated password looks empty/too short. Aborting before touching any role." >&2
  exit 1
fi

run_sql "CREATE ROLE authenticator WITH LOGIN NOINHERIT PASSWORD '$AUTH_PW';" || \
  echo "(role may already exist -- continuing to GRANT)"
run_sql "GRANT anon, authenticated, service_role TO authenticator;"
echo "authenticator role created and granted anon/authenticated/service_role."
echo

echo "=== Step 3: Storing the authenticator connection string in Secrets Manager ==="
DB_URI="postgres://authenticator:${AUTH_PW}@vitana-aurora-prod.cluster-cfk228aiedf3.eu-central-1.rds.amazonaws.com:5432/vitana"
aws secretsmanager create-secret --region "$REGION" \
  --name "vitana/aurora/prod/postgrest-authenticator-uri" \
  --description "PostgREST's DB connection role for the Aurora-staging build (VTID-03619). Login role authenticator, member of anon/authenticated/service_role." \
  --secret-string "$DB_URI" \
  --query 'ARN' --output text
unset AUTH_PW DB_URI

echo
echo "=== Step 4: Restarting the DMS reload ==="
TASK_ARN="arn:aws:dms:eu-central-1:472838866351:task:6HXJWOLRF5FA3DND3TLMGXHY4I"
aws dms start-replication-task --region "$REGION" \
  --replication-task-arn "$TASK_ARN" \
  --start-replication-task-type reload-target \
